'use strict';
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,published,jiraScope={issues:[]},state={mode:'focus',category:'',query:'',team:'',status:'',section:'',owner:'',group:'',dueMonth:'',attention:'',page:0,view:'dashboard',dueField:'due',asOf:new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul'}).format(new Date())};
fetch('jira-history.json').then(r=>r.json()).then(v=>{jiraScope=v; if(data) render();}).catch(()=>{});
const colors={G:'#409776',R:'#d59e36',D:'#c74f64','P-D':'#638ac7',Done:'#0b7f79',Unknown:'#c6ceda'};
const fmt=d=>/^\d{4}-\d{2}-\d{2}$/.test(d)?new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):d||'—';
const badge=r=>`<span class="badge ${esc(r.status)}">${esc(Plan.labels[r.status]||r.status)}</span>`;
const base=()=>data.rows.filter(Analytics.scopes[state.mode].match);
function selected(){return base().filter(r=>(!state.category||r.section===state.category)&&(!state.team||(r.team||'Not recorded')===state.team)&&(!state.status||r.status===state.status)&&(!state.section||r.section===state.section)&&(!state.owner||(r.owner||'Not recorded')===state.owner)&&(!state.group||(r.group||'Not recorded')===state.group)&&(!state.dueMonth||r[state.dueField].startsWith(state.dueMonth))&&(!state.attention||(Analytics.isDate(r[state.dueField])&&r[state.dueField]<state.asOf&&!Analytics.milestoneDone(r,state.dueField)))&&(!state.query||[r.title,r.group,r.section,r.owner,r.team,r.ticket,r.summary,r.sdk].join(' ').toLowerCase().includes(state.query.toLowerCase())));}
function controls(){const rows=base();$('team').innerHTML='<option value="">All teams</option>'+[...new Set(rows.map(r=>r.team||'Not recorded'))].sort().map(t=>`<option>${esc(t)}</option>`).join('');$('status').innerHTML='<option value="">All statuses</option>'+Object.entries(Plan.labels).map(([v,t])=>`<option value="${v}">${t}</option>`).join('');$('section').innerHTML='<option value="">All sections</option>'+[...new Set(rows.map(r=>r.section))].map(t=>`<option>${esc(t)}</option>`).join('');for(const f of ['team','status','section'])$(f).value=state[f];$('search').value=state.query;$('section-label').hidden=state.mode!=='all';}
function render(){
 const rows=selected(),total=base().length;state.page=Math.min(state.page,Math.max(0,Math.ceil(rows.length/25)-1));
 $('page-title').textContent=Analytics.scopes[state.mode].title;
 document.querySelectorAll('#nav button').forEach(b=>{b.classList.toggle('active',b.dataset.mode===state.mode);b.setAttribute('aria-current',b.dataset.mode===state.mode?'page':'false')});
 $('category-cards').hidden=state.mode!=='focus'||state.view==='dashboard';$('category-cards').innerHTML=Plan.focus.map(s=>{const rs=data.rows.filter(r=>r.section===s);return `<button class="category ${state.category===s?'active':''}" data-category="${esc(s)}" aria-pressed="${state.category===s}"><span class="cat-top">${s}</span><span class="cat-count">${rs.length}</span><small>plan rows</small><div class="mini-bar" aria-hidden="true">${Object.entries(colors).map(([k,c])=>`<span style="flex:${rs.filter(r=>r.status===k).length};background:${c}"></span>`).join('')}</div></button>`}).join('');
 const ticketKeys=new Set((jiraScope.issues||[]).map(i=>i.key));const tickets=(rows.filter(r=>ticketKeys.has(r.key)).length?rows.filter(r=>ticketKeys.has(r.key)):jiraScope.issues||[]);const metrics=[['Jira tickets',jiraScope.issues?.length||tickets.length,'Filter 19455',''],['Done for B0',tickets.filter(r=>r.status==='Done'||r.currentStatus==='Done').length,'Current Jira status',''],['Pre-silicon done',tickets.filter(r=>r.status==='P-D'||r.currentStatus==='P-D').length,'Current Jira status',''],['Delayed / risky',tickets.filter(r=>['D','R'].includes(r.status)||['D','R'].includes(r.currentStatus)).length,'Current Jira status','danger'],['Status not recorded',tickets.filter(r=>!r.status&&!r.currentStatus).length,'Jira status unavailable','']];
 $('metrics').innerHTML=metrics.map(([label,n,sub,cls])=>`<div class="metric ${cls}"><span class="caption">${label}</span><strong>${n}</strong><small>${sub}</small></div>`).join('');
 $('list-title').textContent=({history:'Weekly evolution',dates:'Delivery dates',risks:'Early warnings',dependencies:'Dependency review',report:'Management report'})[state.view]|| (state.view==='dashboard'?'Program dashboard':state.mode==='docs'?'Development specifications':state.mode==='all'?'Plan register':Analytics.scopes[state.mode].title);$('count').textContent=`${rows.length} of ${total} rows${state.category?' · '+state.category:''}`;
 const page=rows.slice(state.page*25,(state.page+1)*25);
 $('results').innerHTML=state.view==='dashboard'?renderDashboard(rows):['history','dates','risks','dependencies','report'].includes(state.view)?renderIntelligence(['dates','risks','report'].includes(state.view)?jiraRows(rows):rows):rows.length?(state.view==='schedule'?renderSchedule(page):renderRegister(page)):'<div class="empty">No rows match these filters. Clear filters to see the plan.</div>';
 if(state.view==='dashboard'&&jiraScope.issues?.length){document.querySelectorAll('.cohort').forEach((el,i)=>{if(!el.querySelector('.status-cumulative'))el.insertAdjacentHTML('beforeend',jiraStatusSummary(['focus','req','docs','validation'][i]));});}
 $('schedule-view').hidden=false;for(const v of ['dashboard','register','schedule','history','dates','risks','dependencies','report'])$(v+'-view').setAttribute('aria-pressed',state.view===v);
 document.querySelector('.table-footer').hidden=!['register','schedule'].includes(state.view); document.querySelector('.filters').hidden=state.view==='history'; $('category-cards').hidden=state.view!=='register'||state.mode!=='focus';
 $('chart-filter-label').textContent=[state.section&&'Section: '+state.section,state.owner&&'Assignee: '+state.owner,state.group&&'Group: '+state.group,state.dueMonth&&(state.dueField==='preDue'?'Pre-silicon':'Feature')+' due month: '+state.dueMonth,state.attention&&'Past due date; completion unconfirmed as of '+state.asOf].filter(Boolean).join(' · ');
 if(state.view==='schedule'){const month=new Date().toLocaleString('en-US',{month:'short'}),year=new Date().getFullYear(),index=data.weeks.findIndex(w=>w.month===month&&w.year===year),scroller=$('results').querySelector('.table-scroll');if(scroller&&index>=0)scroller.scrollLeft=index*55;}
 $('page-label').textContent=rows.length?`Rows ${state.page*25+1}–${Math.min((state.page+1)*25,rows.length)} of ${rows.length}`:'0 rows';$('prev').disabled=!state.page;$('next').disabled=(state.page+1)*25>=rows.length;
}
function renderSchedule(rows){
 const months=[];for(const w of data.weeks){const label=w.month+' '+w.year;if(months.at(-1)?.label===label)months.at(-1).span++;else months.push({label,span:1})}
 return `<p class="schedule-legend">Original weekly cells and colors · Click a feature for full annotations and due dates. Colored cells do not by themselves indicate completion.</p><div class="table-scroll"><table class="weekly"><thead><tr><th class="frozen" rowspan="2">Feature / deliverable</th>${months.map(m=>`<th colspan="${m.span}">${m.label}</th>`).join('')}</tr><tr>${data.weeks.map(w=>`<th>${w.week}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td class="frozen feature"><button data-row="${r.row}">${esc(r.title)}</button><span class="subline">${esc(r.key||r.team)} · ${esc(Plan.labels[r.status]||r.status)}</span></td>${data.weeks.map(w=>{const t=r.timeline.find(t=>t.column===w.column);return `<td class="week-cell" title="${esc(w.year+' '+w.week+(t?.text?' · '+t.text:''))}">${t?`<span style="${t.color?'background:#'+t.color+';color:'+contrast(t.color):''}">${esc(t.text)}${!t.text?'<span class="sr-only">Colored schedule cell</span>':''}</span>`:''}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`;
}
function contrast(hex){const nums=hex.match(/../g).map(x=>parseInt(x,16));return nums[0]*.299+nums[1]*.587+nums[2]*.114>145?'#172638':'#ffffff'}
function renderRegister(rows){return `<div class="table-scroll"><table><thead><tr><th>Feature / deliverable</th><th>Owner</th><th>Status</th><th>Pre-silicon due</th><th>Feature Done target</th><th>Jira</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="feature"><button data-row="${r.row}">${esc(r.title)}</button><span class="subline">${esc(r.section)} / ${esc(r.group)} · row ${r.row}${r.sdk?' · '+esc(r.sdk):''}</span></td><td>${esc(r.owner)||'Unassigned'}<span class="subline">${esc(r.team)||'Team not recorded'}</span></td><td>${badge(r)}</td><td class="nowrap">${esc(fmt(r.preDue))}</td><td class="nowrap">${esc(fmt(r.due))}</td><td class="nowrap">${r.url?`<a target="_blank" rel="noopener noreferrer" href="${esc(r.url)}">${esc(r.key||r.ticket)} ↗</a>`:esc(r.ticket)||'—'}</td></tr>`).join('')}</tbody></table></div>`;}
function showDetail(row){const r=data.rows.find(r=>r.row===row);if(!r)return;$('detail-eyebrow').textContent=`${r.section} · Source row ${r.row}`;$('detail-body').innerHTML=`<h2>${esc(r.title)}</h2>${badge(r)}<p>${esc(r.group)}</p><dl class="detail-grid">${[['Team',r.team],['Assignee',r.owner],['SDK version',r.sdk],['Pre-silicon target (H)',fmt(r.preTarget)],['P-D due date (K)',fmt(r.preDue)],['Feature Done target (L)',fmt(r.due)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)||'Not recorded'}</dd></div>`).join('')}</dl><h3>Current progress summary</h3><div class="note">${esc(r.summary)||'No progress summary recorded.'}</div><h3>Source links</h3>${r.links.length?r.links.map(l=>`<p><a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.text)} ↗</a> <small>Column ${l.column}</small></p>`).join(''):r.url?`<p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.key)} ↗</a></p>`:'<p>No link recorded in the worksheet.</p>'}<h3>Weekly plan annotations</h3>${r.timeline.length?`<ul class="timeline-items">${r.timeline.map(t=>`<li><time>${t.year} ${t.week} · ${t.month}</time><span>${t.color?`<i class="color-swatch" style="background:#${t.color}"></i>`:''}${esc(t.text)||'Color-only marker'}</span></li>`).join('')}</ul>`:'<p>No annotations or colored cells in the weekly schedule.</p>'}`;$('detail').showModal();}
function sourceInfo(){$('detail-eyebrow').textContent='DATA SOURCE';$('detail-body').innerHTML='<h2>About this plan</h2><p>'+esc(data.name)+'<br>Worksheet: '+esc(data.sheet)+'</p><p>Refreshes happen only when requested. Load &amp; save workbook retains the original .xlsx file and the parsed first worksheet in persistent storage. Earlier observations remain available in Weekly evolution. Saving errors are shown explicitly; an unsaved import remains in this session.</p><p>Weekly feature totals count workbook rows, including unticketed entries. Historical duedates.db runs contain Jira ticket dates, not complete historic feature records or Level 1 labels. Historical ticket counts use current section mapping. Missing weeks are not interpolated.</p><p>P-D and Feature Done dates are targets. The workbook column L is named Feature Due Date; it is not an actual completion date. Only the recorded Done status supports final completion; P-D indicates the separate pre-silicon milestone. No actual completion date is available.</p><p>Blank owners and statuses remain unknown. Split section labels and inherited groups are preserved. Original weekly colors and annotations do not establish completion. Dependency suggestions are unconfirmed hypotheses requiring owner review; this dashboard never creates Jira links.</p><p>The dashboard does not maintain a live Jira or OneDrive connection. Source snapshots and legacy history show their observation dates. Owner reviews are dashboard records.</p>';$('detail').showModal();}
function updateSource(){$('sheet-name').textContent=data.sheet;$('source').textContent=(data.mode==='saved'?'Saved observation':data.mode==='session'?'Unsaved session import':'Published snapshot')+' · Workbook saved '+new Date(data.modifiedAt).toLocaleString('en-GB',{timeZone:'Asia/Seoul',dateStyle:'medium',timeStyle:'short'})+' KST · Refresh on request';$('footer-source').textContent=data.name;$('reset').hidden=data===published;}
document.addEventListener('click',e=>{const cat=e.target.closest('[data-category]'),r=e.target.closest('[data-row]'),nav=e.target.closest('[data-mode]');if(cat){state.category=state.category===cat.dataset.category?'':cat.dataset.category;state.page=0;render()}if(r)showDetail(Number(r.dataset.row));if(nav){Object.assign(state,{mode:nav.dataset.mode,category:'',query:'',team:'',status:'',section:'',owner:'',group:'',dueMonth:'',attention:'',page:0});controls();render()}});
for(const f of ['team','status','section'])$(f).addEventListener('change',e=>{state[f]=e.target.value;state.page=0;render()});$('search').addEventListener('input',e=>{state.query=e.target.value;state.page=0;render()});$('clear').onclick=()=>{Object.assign(state,{category:'',query:'',team:'',status:'',section:'',owner:'',group:'',dueMonth:'',attention:'',page:0});controls();render()};$('prev').onclick=()=>{state.page--;render()};$('next').onclick=()=>{state.page++;render()};$('close-detail').onclick=()=>$('detail').close();$('source-info').onclick=sourceInfo;
$('import').onclick=()=>$('file').click();
$('file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1024*1024)throw new Error('The durable snapshot limit is 1 MB per workbook.');const bytes=new Uint8Array(await file.arrayBuffer());const next=Plan.parseWorkbook(XLSX.read(bytes,{type:'array',cellDates:true,cellStyles:true}),{name:file.name,modifiedAt:new Date(file.lastModified).toISOString(),mode:'session'});let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));next.workbookBase64=btoa(binary);next.observedAt=new Date().toISOString();data=next;historyState.viewedId='';Object.assign(state,{category:'',query:'',team:'',status:'',section:'',owner:'',group:'',dueMonth:'',attention:'',page:0});controls();updateSource();render();$('message').textContent='Loaded '+data.rows.length+' rows. Saving complete workbook…';try{await saveCurrent();}catch(error){$('message').textContent='Workbook loaded but NOT saved: '+error.message+' Keep this page open and retry Record current workbook in Weekly evolution.';}}catch(err){$('message').textContent='Could not load workbook: '+err.message;}finally{e.target.value='';}};
$('reset').onclick=()=>{data=published;historyState.viewedId="";Object.assign(state,{category:'',query:'',team:'',status:'',section:'',owner:'',group:'',dueMonth:'',attention:'',page:0});controls();updateSource();render();$('message').textContent='Restored the published workbook snapshot.'};
for(const view of ['dashboard','register','schedule','history','dates','risks','dependencies','report'])$(view+'-view').onclick=()=>{state.view=view;render()};
if(document.modelContext?.registerTool){const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'filter_master_plan',title:'Filter the master plan',description:'Change the visible plan view and search text. Returns matching row counts and up to 25 visible rows; does not change workbook data.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['focus','req','docs','validation','all']},query:{type:'string',maxLength:200},status:{type:'string',enum:['','G','R','D','P-D','Done','Unknown']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!data)throw new Error('The workbook is still loading.');if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['mode','query','status'].includes(k))||!['focus','req','docs','validation','all'].includes(input.mode)||('query'in input&&(typeof input.query!=='string'||input.query.length>200))||('status'in input&&!['','G','R','D','P-D','Done','Unknown'].includes(input.status)))throw new Error('Invalid plan filters.');Object.assign(state,{mode:input.mode,query:input.query||'',status:input.status||'',team:'',category:'',section:'',owner:'',group:'',dueMonth:'',attention:'',page:0});controls();render();const rows=selected();return {count:rows.length,rows:rows.slice(0,25).map(r=>({row:r.row,title:r.title,key:r.key,status:r.status,due:r.due}))};}},{signal:life.signal})).catch(()=>{});}catch{}}
fetch('source.json').then(r=>{if(!r.ok)throw new Error('Source could not be loaded');return r.json()}).then(d=>{data=published=d;controls();updateSource();render();initIntelligence()}).catch(e=>{$('message').textContent=e.message+'. Reload this page to try again.'});
